import { createContext, useContext, useEffect, useMemo, useRef, type ReactNode } from 'react';
import { useMail } from './store';
import { useUI, clearSelection, setUI } from './ui';
import { useRoute, hrefFor, type Route } from './router';
import { FOLDER_META, listRowsForFolder, listRowsForLabel, type Row, type ViewSpec } from './mail';
import { runSearch } from './search';

export const PAGE_SIZE = 50;

export interface ViewModel {
  route: Route;
  page: 'mail' | 'settings';
  view: ViewSpec;
  viewKey: string;
  rows: Row[];
  pageRows: Row[];
  pageIndex: number;
  pageCount: number;
  highlight: string[];
  title: string;
  threadId?: string;
  /** Row that owns the open conversation, if visible in this view. */
  hrefFor: (threadId?: string, pageIndex?: number) => string;
}

const INBOX_VIEW: ViewSpec = { kind: 'folder', folder: 'inbox', tab: 'primary' };

const Ctx = createContext<ViewModel | null>(null);

export function viewKeyOf(view: ViewSpec): string {
  switch (view.kind) {
    case 'folder':
      return `f:${view.folder}:${view.tab ?? ''}`;
    case 'label':
      return `l:${view.labelId}`;
    case 'search':
      return `s:${view.query}`;
  }
}

export function ViewProvider({ children }: { children: ReactNode }) {
  const route = useRoute();
  const mail = useMail();
  const { now } = useUI();
  const view: ViewSpec = route.page === 'mail' ? route.view : INBOX_VIEW;
  const viewKey = viewKeyOf(view);

  const result = useMemo(() => {
    if (route.page !== 'mail') return { rows: [] as Row[], highlight: [] as string[] };
    if (view.kind === 'folder') return { rows: listRowsForFolder(mail, view.folder, now, view.tab), highlight: [] as string[] };
    if (view.kind === 'label') return { rows: listRowsForLabel(mail, view.labelId), highlight: [] as string[] };
    return runSearch(mail, view.query, now);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mail, viewKey, now, route.page]);

  const pageIndexRaw = route.page === 'mail' ? route.pageIndex : 0;
  const pageCount = Math.max(1, Math.ceil(result.rows.length / PAGE_SIZE));
  const pageIndex = Math.min(pageIndexRaw, pageCount - 1);
  const pageRows = useMemo(() => result.rows.slice(pageIndex * PAGE_SIZE, (pageIndex + 1) * PAGE_SIZE), [result.rows, pageIndex]);

  const title = useMemo(() => {
    if (view.kind === 'folder') return FOLDER_META[view.folder].label;
    if (view.kind === 'label') return mail.labels.find((l) => l.id === view.labelId)?.name ?? 'Label';
    return 'Search results';
  }, [view, mail.labels]);

  const threadId = route.page === 'mail' ? route.threadId : undefined;

  const vm = useMemo<ViewModel>(
    () => ({
      route,
      page: route.page,
      view,
      viewKey,
      rows: result.rows,
      pageRows,
      pageIndex,
      pageCount,
      highlight: result.highlight,
      title,
      threadId,
      hrefFor: (id, p = pageIndex) => hrefFor(view, id, id ? 0 : p),
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [route, viewKey, result, pageRows, pageIndex, pageCount, title, threadId],
  );

  // A different view starts with a clean selection and cursor.
  const prevKey = useRef(viewKey);
  useEffect(() => {
    if (prevKey.current !== viewKey) {
      prevKey.current = viewKey;
      clearSelection();
      setUI({ cursor: null });
    }
  }, [viewKey]);

  return <Ctx.Provider value={vm}>{children}</Ctx.Provider>;
}

export function useViewModel(): ViewModel {
  const v = useContext(Ctx);
  if (!v) throw new Error('ViewProvider missing');
  return v;
}

/** Thread ids covered by the current selection ("select all" spans every page). */
export function selectedRows(rows: Row[], keys: string[], allInView: boolean): Row[] {
  if (allInView) return rows;
  const set = new Set(keys);
  return rows.filter((r) => set.has(r.key));
}

export function uniqueThreadIds(rows: Row[]): string[] {
  return [...new Set(rows.map((r) => r.thread.id))];
}

import { useSyncExternalStore } from 'react';
import type { Address, Attachment } from './types';
import { uid } from './mail';

export interface Toast {
  id: string;
  message: string;
  actions: { label: string; run: () => void }[];
  duration: number;
  tone?: 'default' | 'error';
}

export interface ComposeSeed {
  to?: Address[];
  cc?: Address[];
  bcc?: Address[];
  subject?: string;
  html?: string;
  quoteHtml?: string;
  attachments?: Attachment[];
  replyToMessageId?: string;
}

export interface ComposeWin {
  id: string;
  draftId: string;
  threadId: string;
  mode: 'new' | 'reply' | 'replyAll' | 'forward';
  minimized: boolean;
  maximized: boolean;
  /** Reply windows render inline in the open conversation until popped out. */
  popped?: boolean;
  seed?: ComposeSeed;
}

export type Dialog =
  | { kind: 'confirm'; title: string; body: string; confirmLabel: string; danger?: boolean; onConfirm: () => void }
  | { kind: 'alert'; title: string; body: string }
  | { kind: 'shortcuts' }
  | { kind: 'label'; labelId?: string; applyToIds?: string[] }
  | { kind: 'snooze'; ids: string[] }
  | { kind: 'schedule'; onPick: (ts: number) => void }
  | { kind: 'attachment'; threadId: string; messageId: string; attachmentId: string }
  | { kind: 'link'; onInsert: (text: string, url: string) => void; initialText: string };

export interface UIState {
  now: number;
  selection: { keys: string[]; allInView: boolean };
  cursor: string | null;
  toasts: Toast[];
  composes: ComposeWin[];
  drawerOpen: boolean;
  dialog: Dialog | null;
  lastUndo: (() => void) | null;
  /** Row key focused by keyboard navigation in the message list. */
  searchFocusTick: number;
}

let ui: UIState = {
  now: Date.now(),
  selection: { keys: [], allInView: false },
  cursor: null,
  toasts: [],
  composes: [],
  drawerOpen: false,
  dialog: null,
  lastUndo: null,
  searchFocusTick: 0,
};

const listeners = new Set<() => void>();

export function getUI(): UIState {
  return ui;
}

export function setUI(patch: Partial<UIState> | ((u: UIState) => Partial<UIState>)) {
  const p = typeof patch === 'function' ? patch(ui) : patch;
  ui = { ...ui, ...p };
  listeners.forEach((l) => l());
}

export function useUI(): UIState {
  return useSyncExternalStore(
    (l) => {
      listeners.add(l);
      return () => {
        listeners.delete(l);
      };
    },
    getUI,
    getUI,
  );
}

/* ---------- toasts ---------- */

const toastTimers = new Map<string, ReturnType<typeof setTimeout>>();

export function toast(
  message: string,
  opts: { actions?: { label: string; run: () => void }[]; duration?: number; tone?: 'default' | 'error' } = {},
): string {
  const id = uid('toast');
  const duration = opts.duration ?? (opts.actions?.length ? 7000 : 4000);
  const t: Toast = { id, message, actions: opts.actions ?? [], duration, tone: opts.tone };
  setUI((u) => ({ toasts: [...u.toasts.slice(-2), t] }));
  toastTimers.set(
    id,
    setTimeout(() => dismissToast(id), duration),
  );
  return id;
}

export function dismissToast(id: string) {
  const timer = toastTimers.get(id);
  if (timer) clearTimeout(timer);
  toastTimers.delete(id);
  setUI((u) => ({ toasts: u.toasts.filter((t) => t.id !== id) }));
}

export function pauseToast(id: string) {
  const timer = toastTimers.get(id);
  if (timer) clearTimeout(timer);
  toastTimers.delete(id);
}

export function resumeToast(id: string, ms = 3000) {
  if (toastTimers.has(id)) return;
  toastTimers.set(
    id,
    setTimeout(() => dismissToast(id), ms),
  );
}

/* ---------- selection ---------- */

export function clearSelection() {
  if (ui.selection.keys.length || ui.selection.allInView) setUI({ selection: { keys: [], allInView: false } });
}

export function setSelection(keys: string[], allInView = false) {
  setUI({ selection: { keys, allInView } });
}

export function toggleSelected(key: string) {
  const cur = ui.selection.keys;
  const keys = cur.includes(key) ? cur.filter((k) => k !== key) : [...cur, key];
  setUI({ selection: { keys, allInView: false } });
}

/* ---------- compose windows ---------- */

export function openCompose(opts: {
  mode?: ComposeWin['mode'];
  threadId?: string;
  draftId?: string;
  seed?: ComposeSeed;
}): string {
  const existing = opts.draftId ? ui.composes.find((c) => c.draftId === opts.draftId) : undefined;
  if (existing) {
    setUI((u) => ({
      composes: u.composes.map((c) => (c.id === existing.id ? { ...c, minimized: false } : c)),
    }));
    return existing.id;
  }
  const win: ComposeWin = {
    id: uid('win'),
    draftId: opts.draftId ?? uid('m'),
    threadId: opts.threadId ?? uid('t'),
    mode: opts.mode ?? 'new',
    minimized: false,
    maximized: false,
    seed: opts.seed,
  };
  setUI((u) => {
    const next = [...u.composes, win];
    // Keep at most three expanded windows: minimise the oldest extras.
    let open = next.filter((c) => !c.minimized).length;
    const adjusted = next.map((c) => {
      if (open > 3 && !c.minimized && c.id !== win.id) {
        open--;
        return { ...c, minimized: true };
      }
      return c;
    });
    return { composes: adjusted };
  });
  return win.id;
}

export function updateCompose(id: string, patch: Partial<ComposeWin>) {
  setUI((u) => ({ composes: u.composes.map((c) => (c.id === id ? { ...c, ...patch } : c)) }));
}

export function closeCompose(id: string) {
  setUI((u) => ({ composes: u.composes.filter((c) => c.id !== id) }));
}

export function openDialog(d: Dialog) {
  setUI({ dialog: d });
}

export function closeDialog() {
  setUI({ dialog: null });
}

export function confirmDialog(opts: { title: string; body: string; confirmLabel: string; danger?: boolean }, onConfirm: () => void) {
  openDialog({ kind: 'confirm', ...opts, onConfirm });
}

import { useEffect, useState } from 'react';
import type { Settings } from './types';
import { tick } from './actions';
import { getUI, setUI, toast } from './ui';
import { navigate } from './router';
import { getState } from './store';

export type Viewport = 'mobile' | 'tablet' | 'desktop';

function viewportNow(): Viewport {
  const w = window.innerWidth;
  return w < 760 ? 'mobile' : w < 1100 ? 'tablet' : 'desktop';
}

export function useViewport(): Viewport {
  const [vp, setVp] = useState<Viewport>(viewportNow);
  useEffect(() => {
    const on = () => setVp(viewportNow());
    window.addEventListener('resize', on);
    return () => window.removeEventListener('resize', on);
  }, []);
  return vp;
}

function systemDark(): boolean {
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ?? false;
}

export function applyPrefs(s: Pick<Settings, 'theme' | 'accent' | 'density'>) {
  const root = document.documentElement;
  const dark = s.theme === 'dark' || (s.theme === 'system' && systemDark());
  root.dataset.theme = dark ? 'dark' : 'light';
  root.dataset.accent = s.accent;
  root.dataset.density = s.density;
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', dark ? '#111318' : '#f6f8fc');
}

export function usePrefs(settings: Settings) {
  useEffect(() => {
    applyPrefs(settings);
    if (settings.theme !== 'system') return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const on = () => applyPrefs(settings);
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, [settings.theme, settings.accent, settings.density]); // eslint-disable-line react-hooks/exhaustive-deps
}

/** Drives snooze expiry, scheduled sends, simulated replies and the relative-time clock. */
export function useTicker() {
  useEffect(() => {
    const run = () => {
      const now = Date.now();
      setUI({ now });
      for (const ev of tick(now)) {
        const thread = getState().threads[ev.threadId];
        const subject = thread?.subject || '(no subject)';
        if (ev.kind === 'reply' || ev.kind === 'incoming') {
          toast(`New message${ev.from ? ` from ${ev.from}` : ''}: ${subject}`, {
            actions: [{ label: 'View', run: () => navigate(`#/inbox/${encodeURIComponent(ev.threadId)}`) }],
            duration: 6000,
          });
        } else if (ev.kind === 'snooze') {
          toast(`Snoozed conversation is back in your inbox: ${subject}`, {
            actions: [{ label: 'View', run: () => navigate(`#/inbox/${encodeURIComponent(ev.threadId)}`) }],
            duration: 6000,
          });
        } else if (ev.kind === 'scheduled') {
          toast(`Scheduled message sent: ${subject}`, { duration: 5000 });
        }
      }
    };
    run();
    const id = setInterval(run, 5000);
    const onVis = () => document.visibilityState === 'visible' && run();
    document.addEventListener('visibilitychange', onVis);
    return () => {
      clearInterval(id);
      document.removeEventListener('visibilitychange', onVis);
    };
  }, []);
}

export function useMediaQuery(q: string): boolean {
  const [m, setM] = useState(() => window.matchMedia(q).matches);
  useEffect(() => {
    const mq = window.matchMedia(q);
    const on = () => setM(mq.matches);
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, [q]);
  return m;
}

export const nowTs = () => getUI().now;

