+
+  const mobile = vp === 'mobile';
+  return (
+    <div
+      ref={root}
+      className={`compose-win${win.minimized ? ' minimized' : ''}${win.maximized ? ' maximized' : ''}${dragOver ? ' drag' : ''}`}
