+    <>
+      {maximized && <div className="compose-scrim" aria-hidden="true" />}
+      <div className={`compose-dock${vp === 'mobile' ? ' mobile' : ''}`}>
+        {[...wins].reverse().map((w) => (
+          <Composer key={w.id} win={w} variant="window" />
+        ))}
+      </div>
+    </>
+  );
+}
+
+export type { Ref };
+export { deliveredMessages };

