              {d.confirmLabel}
            </button>
          </div>
        </Modal>
      );
    case 'alert':
      return (
        <Modal title={d.title} onClose={closeDialog}>
          <p>{d.body}</p>
          <div className="dialog-actions">
            <button type="button" className="btn primary" onClick={closeDialog}>
              OK
            </button>
          </div>
        </Modal>
