:root {
  --tooltip-fg: #fff;
}
:root[data-theme='dark'] {
  --tooltip-fg: #1f1f1f;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  position: relative;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -48px;
  z-index: 3000;
  background: var(--accent);
  color: var(--on-accent);
  padding: 8px 16px;
  border-radius: 20px;
  text-decoration: none;
  transition: top 0.15s;
}
.skip-link:focus {
  top: 8px;
}

/* tooltips */
[data-tip] {
  position: relative;
}
@media (hover: hover) {
  [data-tip]:hover::after,
  [data-tip]:focus-visible::after {
    content: attr(data-tip);
    position: absolute;
    top: calc(100% + 4px);
    left: 50%;
    transform: translateX(-50%);
    background: var(--tooltip-bg);
    color: var(--tooltip-fg);
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 500;
    line-height: 16px;
    padding: 4px 8px;
    border-radius: 4px;
    white-space: nowrap;
    z-index: 2000;
    pointer-events: none;
    animation: tip-in 0.1s 0.55s both;
  }
  .app[data-vp='desktop'] .sidebar.collapsed [data-tip]:hover::after {
    top: 50%;
    left: calc(100% + 6px);
    transform: translateY(-50%);
  }
}
@keyframes tip-in {
  from {
    opacity: 0;
  }
}

/* ---------- header ---------- */
.header {
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 16px 0 8px;
  flex-shrink: 0;
  position: relative;
  z-index: 20;
}
.header-left {
  display: flex;
  align-items: center;
  gap: 4px;
  width: calc(var(--sidebar-w) - 16px);
  flex-shrink: 0;
  min-width: 0;
}
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--text-2);
  min-width: 0;
  padding: 4px 8px 4px 4px;
  border-radius: 8px;
}
.wordmark {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 20px;
  line-height: 24px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--text-2);
  white-space: nowrap;
}
.logo-mark {
  flex-shrink: 0;
}
.header-search {
  flex: 1 1 auto;
  max-width: 720px;
  min-width: 0;
}
.header-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.account-btn {
  border-radius: 50%;
  padding: 4px;
  margin-left: 4px;
  display: inline-flex;
}
.account-btn:hover {
  background: var(--hover);
}
.header.searching {
  padding: 8px;
}

/* ---------- search ---------- */
.searchbar {
  display: flex;
  align-items: center;
  height: 48px;
  border-radius: 24px;
  background: var(--surface-search);
  padding: 0 4px;
  transition: background 0.15s, box-shadow 0.15s;
  width: 100%;
}
.searchbar:hover:not(.focused) {
  box-shadow: var(--shadow-1);
}
.searchbar.focused {
  background: var(--surface-search-focus);
  box-shadow: var(--shadow-2);
}
.searchbar input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: none;
  background: transparent;
  font-size: 16px;
  font-family: var(--font-text);
  color: var(--text);
}
.searchbar input::placeholder {
  color: var(--text-3);
}
.searchbar.mobile-open {
  height: 48px;
}
.search-suggest {
  padding: 8px 0;
  border-radius: 0 0 24px 24px;
  margin-top: -4px;
}
.suggest-row {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 40px;
  padding: 4px 20px;
  cursor: pointer;
}
.suggest-row.active,
.suggest-row:hover {
  background: var(--hover);
}
.suggest-row .icon {
  color: var(--text-3);
  font-size: 20px;
}
.suggest-primary {
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.suggest-secondary {
  color: var(--text-3);
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.suggest-remove {
  margin-left: auto;
  color: var(--accent);
  font-size: 13px;
  padding: 4px 8px;
  border-radius: 4px;
}
.suggest-remove:hover {
  background: var(--hover);
}
.suggest-chips {
  border-top: 1px solid var(--line);
  margin-top: 8px;
  padding-top: 8px;
}
.suggest-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 4px 16px 8px;
}
.suggest-chip {
  height: 28px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  font-size: 13px;
  color: var(--text-2);
  font-family: var(--font-text);
}
.suggest-chip:hover {
  background: var(--hover);
}

.adv-search {
  padding: 16px 20px 12px;
  border-radius: 16px;
  margin-top: -4px;
}
.adv-form {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 12px 12px;
  align-items: center;
  font-size: 13px;
}
.adv-form label {
  color: var(--text-3);
}
.adv-input {
  height: 32px;
  border: 0;
  border-bottom: 1px solid var(--line-strong);
  background: transparent;
  outline: none;
  padding: 0 4px;
  min-width: 0;
  width: 100%;
  font-size: 14px;
}
.adv-input:focus {
  border-bottom: 2px solid var(--accent);
}
select.adv-input option {
  color: #1f1f1f;
}
.adv-row {
  display: flex;
  gap: 8px;
}
.adv-check {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-2) !important;
}
.adv-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 4px;
}

/* ---------- quick settings & account ---------- */
.quick-settings {
  width: 340px;
  padding: 0;
  border-radius: 16px;
}
.qs-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 16px 8px;
}
.qs-head .btn {
  height: 32px;
  padding: 0 14px;
  font-size: 13px;
}
.qs-section {
  padding: 12px 16px;
  border-top: 1px solid var(--line);
}
.qs-title {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-3);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.segmented {
  display: flex;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  overflow: hidden;
}
.segmented button {
  flex: 1;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-2);
  padding: 0 8px;
  white-space: nowrap;
}
.segmented button + button {
  border-left: 1px solid var(--line-strong);
}
.segmented button:hover {
  background: var(--hover);
}
.segmented button.on {
  background: var(--accent-container);
  color: var(--on-accent-container);
  font-weight: 500;
}
.swatches {
  display: flex;
  gap: 10px;
  margin-top: 12px;
}
.swatches.wrap {
  flex-wrap: wrap;
  margin-top: 4px;
}
.swatch {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.12);
}
.swatch.on {
  box-shadow: 0 0 0 2px var(--surface-raised), 0 0 0 4px currentColor;
}
.swatch.on {
  outline: 2px solid var(--text-2);
  outline-offset: 2px;
  box-shadow: none;
}
.switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 36px;
  gap: 16px;
  cursor: pointer;
}
.switch-row input,
.toggle input {
  appearance: none;
  -webkit-appearance: none;
  position: relative;
  width: 40px;
  height: 24px;
  border-radius: 12px;
  background: var(--line-strong);
  cursor: pointer;
  transition: background 0.15s;
  margin: 0;
  flex-shrink: 0;
}
.switch-row input::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}
.switch-row input:checked {
  background: var(--accent);
}
.switch-row input:checked::after {
  transform: translateX(16px);
}
.account-menu {
  width: 340px;
  padding: 0;
  border-radius: 28px;
  background: var(--surface-raised);
}
.account-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px 24px 16px;
  gap: 8px;
}
.account-email {
  font-size: 14px;
  color: var(--text-2);
  align-self: center;
}
.account-name {
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
  margin: 4px 0 8px;
}
.account-storage {
  width: 100%;
  background: var(--bg);
  border-radius: 12px;
  padding: 12px 16px;
}
.storage-bar {
  height: 6px;
  border-radius: 3px;
  background: var(--line);
  overflow: hidden;
}
.storage-bar span {
  display: block;
  height: 100%;
  background: var(--accent);
  border-radius: 3px;
}
.storage-text {
  margin-top: 8px;
  font-size: 12px;
  color: var(--text-3);
}
.account-actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
.account-actions .btn {
  height: 36px;
  padding: 0 16px;
}
.account-foot {
  font-size: 12px;
  color: var(--text-3);
  margin-top: 4px;
}

/* ---------- body / sidebar ---------- */
.app-body {
  flex: 1;
  display: flex;
  min-height: 0;
  position: relative;
}
.sidebar {
  width: var(--sidebar-w);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  transition: width 0.18s ease;
  overflow: hidden;
}
.sidebar.collapsed {
  width: var(--rail-w);
}
.compose-btn {
  margin: 8px 0 16px 8px;
  height: 56px;
  padding: 0 24px 0 16px;
  border-radius: 16px;
  background: var(--compose);
  color: var(--on-compose);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-ui);
  font-weight: 500;
  font-size: 14px;
  align-self: flex-start;
  flex-shrink: 0;
  transition: box-shadow 0.15s, background 0.15s;
}
.compose-btn:hover {
  background: var(--compose-hover);
  box-shadow: var(--shadow-2);
}
.sidebar.collapsed .compose-btn {
  width: 56px;
  padding: 0;
  justify-content: center;
  margin-left: 8px;
}
.nav-scroll {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding-bottom: 16px;
}
.nav-row {
  position: relative;
  display: flex;
  align-items: center;
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 32px;
  padding: 0 12px 0 26px;
  flex: 1;
  min-width: 0;
  border-radius: 0 16px 16px 0;
  margin-right: 8px;
  color: var(--text-2);
  text-decoration: none;
  font-size: 14px;
  font-family: var(--font-ui);
  text-align: left;
}
.nav-item .icon {
  font-size: 20px;
  color: var(--text-2);
}
.nav-item:hover {
  background: var(--hover);
}
.nav-row.active .nav-item {
  background: var(--accent-container);
  color: var(--on-accent-container);
  font-weight: 700;
}
.nav-row.active .nav-item .icon {
  color: var(--on-accent-container);
}
.nav-row.sub .nav-item {
  padding-left: 40px;
}
.nav-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nav-count {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-2);
}
.nav-row.active .nav-count {
  color: var(--on-accent-container);
}
.nav-more {
  width: calc(100% - 8px);
}
.nav-more:disabled {
  opacity: 0.6;
  cursor: default;
}
.nav-group-title {
  padding: 8px 12px 4px 26px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.nav-section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 12px 4px 26px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  font-family: var(--font-ui);
}
.nav-empty {
  padding: 4px 16px 8px 26px;
  font-size: 12px;
  color: var(--text-3);
}
.nav-item.manage {
  margin-top: 4px;
}
.label-dot {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  flex-shrink: 0;
  display: inline-block;
}
.label-dot.big {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}
.nav-item > .label-dot {
  margin: 0 4px;
}
.nav-more-btn {
  position: absolute;
  right: 12px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  color: var(--text-2);
  background: var(--bg);
}
.nav-row:hover .nav-more-btn,
.nav-more-btn:focus-visible {
  opacity: 1;
}
.nav-row:hover .nav-count {
  visibility: hidden;
}
.nav-more-btn:hover {
  background: var(--hover-strong);
}
.nav-row.active .nav-more-btn {
  background: var(--accent-container);
}
.sidebar.collapsed .nav-item {
  width: 48px;
  height: 48px;
  flex: none;
  padding: 0;
  justify-content: center;
  border-radius: 50%;
  margin: 0 0 0 12px;
}
.sidebar.collapsed .nav-row {
  justify-content: flex-start;
}
.sidebar.collapsed .nav-item .icon {
  font-size: 22px;
}
.nav-badge {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}
.sidebar.collapsed .nav-item {
  position: relative;
}

.main {
  flex: 1;
  min-width: 0;
  margin: 0 16px 16px 0;
  background: var(--surface);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  outline: none;
}
.main > * {
  flex: 1;
  min-height: 0;
}

/* drawer (tablet + mobile) */
.sidebar.drawer {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1150;
  width: min(300px, 86vw);
  background: var(--bg);
  transform: translateX(-102%);
  transition: transform 0.22s ease;
  border-radius: 0 16px 16px 0;
  box-shadow: none;
  padding-top: env(safe-area-inset-top);
}
.sidebar.drawer.open {
  transform: translateX(0);
  box-shadow: var(--shadow-3);
}
.drawer-head {
  height: 56px;
  padding: 0 24px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.drawer-title {
  font-family: var(--font-ui);
  font-size: 22px;
  color: var(--text-2);
}
.scrim {
  position: fixed;
  inset: 0;
  background: var(--scrim);
  z-index: 1140;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
}
.scrim.open {
  opacity: 1;
  pointer-events: auto;
}

/* utility */
.tb-spacer {
  flex: 1;
}
.link-btn {
  color: var(--accent);
  font-weight: 500;
  padding: 2px 4px;
  border-radius: 4px;
  font-size: inherit;
  text-align: left;
}
.link-btn:hover {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  text-decoration: underline;
}
.spin .icon {
  animation: spin 0.7s linear;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.fab {
  position: fixed;
  right: 16px;
  bottom: calc(16px + env(safe-area-inset-bottom));
  z-index: 40;
  height: 56px;
  padding: 0 20px 0 16px;
  border-radius: 16px;
  background: var(--compose);
  color: var(--on-compose);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-ui);
  font-weight: 500;
  box-shadow: var(--shadow-2);
}

:root {
  --tooltip-fg: #fff;
}
:root[data-theme='dark'] {
  --tooltip-fg: #1f1f1f;
}

.app {
