  margin-top: 12px;
}
.swatches.wrap {
  flex-wrap: wrap;
  margin-top: 4px;
}
.swatch {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.12);
}
.swatch.on {
  box-shadow: 0 0 0 2px var(--surface-raised), 0 0 0 4px currentColor;
}
.swatch.on {
  outline: 2px solid var(--text-2);
  outline-offset: 2px;
  box-shadow: none;
}
.switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 36px;
  gap: 16px;
  cursor: pointer;
}
.switch-row input,
.toggle input {
  appearance: none;
  -webkit-appearance: none;
  position: relative;
  width: 40px;
  height: 24px;
  border-radius: 12px;
  background: var(--line-strong);
  cursor: pointer;
  transition: background 0.15s;
  margin: 0;
  flex-shrink: 0;
}
.switch-row input::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}
.switch-row input:checked {
  background: var(--accent);
}
.switch-row input:checked::after {
  transform: translateX(16px);
}
.account-menu {
  width: 340px;
  padding: 0;
  border-radius: 28px;
  background: var(--surface-raised);
}
.account-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px 24px 16px;
  gap: 8px;
}
.account-email {
  font-size: 14px;
  color: var(--text-2);
  align-self: center;
}
.account-name {
  font-family: var(--font-ui);
  font-size: 22px;
  font-weight: 400;
  margin: 4px 0 8px;
}
.account-storage {
  width: 100%;
  background: var(--bg);
  border-radius: 12px;
  padding: 12px 16px;
}
.storage-bar {
  height: 6px;
  border-radius: 3px;
  background: var(--line);
  overflow: hidden;
}
.storage-bar span {
  display: block;
  height: 100%;
  background: var(--accent);
  border-radius: 3px;
}
.storage-text {
  margin-top: 8px;
  font-size: 12px;
  color: var(--text-3);
}
.account-actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
.account-actions .btn {
  height: 36px;
  padding: 0 16px;
}
.account-foot {
  font-size: 12px;
  color: var(--text-3);
  margin-top: 4px;
}

/* ---------- body / sidebar ---------- */
.app-body {
  flex: 1;
  display: flex;
  min-height: 0;
  position: relative;
}
.sidebar {
  width: var(--sidebar-w);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  transition: width 0.18s ease;
  overflow: hidden;
}
.sidebar.collapsed {
  width: var(--rail-w);
}
.compose-btn {
  margin: 8px 0 16px 8px;
  height: 56px;
  padding: 0 24px 0 16px;
  border-radius: 16px;
  background: var(--compose);
  color: var(--on-compose);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-ui);
  font-weight: 500;
  font-size: 14px;
  align-self: flex-start;
  flex-shrink: 0;
  transition: box-shadow 0.15s, background 0.15s;
}
.compose-btn:hover {
  background: var(--compose-hover);
  box-shadow: var(--shadow-2);
}
.sidebar.collapsed .compose-btn {
  width: 56px;
  padding: 0;
  justify-content: center;
  margin-left: 8px;
}
.nav-scroll {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding-bottom: 16px;
}
.nav-row {
  position: relative;
  display: flex;
  align-items: center;
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 32px;
  padding: 0 12px 0 26px;
  flex: 1;
  min-width: 0;
  border-radius: 0 16px 16px 0;
  margin-right: 8px;
  color: var(--text-2);
  text-decoration: none;
  font-size: 14px;
  font-family: var(--font-ui);
  text-align: left;
}
.nav-item .icon {
  font-size: 20px;
  color: var(--text-2);
}
.nav-item:hover {
  background: var(--hover);
}
.nav-row.active .nav-item {
  background: var(--accent-container);
  color: var(--on-accent-container);
  font-weight: 700;
}
.nav-row.active .nav-item .icon {
  color: var(--on-accent-container);
}
.nav-row.sub .nav-item {
  padding-left: 40px;
}
.nav-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nav-count {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-2);
}
.nav-row.active .nav-count {
  color: var(--on-accent-container);
}
.nav-more {
  width: calc(100% - 8px);
}
.nav-more:disabled {
  opacity: 0.6;
  cursor: default;
}
.nav-group-title {
  padding: 8px 12px 4px 26px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.nav-section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 12px 4px 26px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  font-family: var(--font-ui);
}
.nav-empty {
  padding: 4px 16px 8px 26px;
  font-size: 12px;
  color: var(--text-3);
}
.nav-item.manage {
  margin-top: 4px;
}
.label-dot {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  flex-shrink: 0;
  display: inline-block;
}
.label-dot.big {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}
.nav-item > .label-dot {
  margin: 0 4px;
}
.nav-more-btn {
  position: absolute;
  right: 12px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  color: var(--text-2);
  background: var(--bg);
}
.nav-row:hover .nav-more-btn,
.nav-more-btn:focus-visible {
  opacity: 1;
}
.nav-row:hover .nav-count {
  visibility: hidden;
}
.nav-more-btn:hover {
  background: var(--hover-strong);
}
.nav-row.active .nav-more-btn {
  background: var(--accent-container);
}
.sidebar.collapsed .nav-item {
  width: 48px;
  height: 48px;
  flex: none;
  padding: 0;
  justify-content: center;
  border-radius: 50%;
  margin: 0 0 0 12px;
}
.sidebar.collapsed .nav-row {
  justify-content: flex-start;
}
.sidebar.collapsed .nav-item .icon {
  font-size: 22px;
}
.nav-badge {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}
.sidebar.collapsed .nav-item {
  position: relative;
}

.main {
  flex: 1;
  min-width: 0;
  margin: 0 16px 16px 0;
  background: var(--surface);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  outline: none;
}
.main > * {
  flex: 1;
  min-height: 0;
}

/* drawer (tablet + mobile) */
.sidebar.drawer {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1150;
  width: min(300px, 86vw);
  background: var(--bg);
  transform: translateX(-102%);
  transition: transform 0.22s ease;
  border-radius: 0 16px 16px 0;
  box-shadow: none;
  padding-top: env(safe-area-inset-top);
}
.sidebar.drawer.open {
  transform: translateX(0);
  box-shadow: var(--shadow-3);
}
.drawer-head {
  height: 56px;
  padding: 0 24px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.drawer-title {
  font-family: var(--font-ui);
  font-size: 22px;
  color: var(--text-2);
}
.scrim {
  position: fixed;
  inset: 0;
  background: var(--scrim);
  z-index: 1140;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
}
.scrim.open {
  opacity: 1;
  pointer-events: auto;
}

/* utility */
.tb-spacer {
  flex: 1;
}
.link-btn {
  color: var(--accent);
  font-weight: 500;
  padding: 2px 4px;
  border-radius: 4px;
  font-size: inherit;
  text-align: left;
}
.link-btn:hover {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  text-decoration: underline;
}
.spin .icon {
  animation: spin 0.7s linear;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.fab {
  position: fixed;
  right: 16px;
  bottom: calc(16px + env(safe-area-inset-bottom));
  z-index: 40;
  height: 56px;
  padding: 0 20px 0 16px;
  border-radius: 16px;
  background: var(--compose);
  color: var(--on-compose);
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-ui);
  font-weight: 500;
  box-shadow: var(--shadow-2);
}

success.content:
:root {
  --font-ui: 'Google Sans Flex Variable', 'Google Sans', 'Product Sans', Roboto, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-text: Roboto, 'Helvetica Neue', Arial, system-ui, sans-serif;

  --accent: #0b57d0;
  --accent-hover: #0a4cb8;
  --accent-container: #d3e3fd;
  --on-accent-container: #041e49;
  --accent-tint: #c2dbff;
  --compose: #c2e7ff;
  --compose-hover: #b3dcf7;
  --on-compose: #001d35;
  --on-accent: #ffffff;

  --bg: #f6f8fc;
  --surface: #ffffff;
  --surface-read: #f2f6fc;
  --surface-search: #e9eef6;
  --surface-search-focus: #ffffff;
  --surface-raised: #ffffff;
  --text: #1f1f1f;
  --text-2: #444746;
  --text-3: #5e5e5e;
  --text-4: #80868b;
  --line: #e1e3e1;
  --line-strong: #c7c7c7;
  --hover: rgba(31, 31, 31, 0.08);
  --hover-strong: rgba(31, 31, 31, 0.12);
  --star: #f5b400;
  --important: #f5b400;
  --danger: #b3261e;
  --danger-container: #f9dedc;
  --success: #146c2e;
  --scrim: rgba(32, 33, 36, 0.4);
  --tooltip-bg: #3c4043;
  --blue: var(--accent);

  --shadow-1: 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
  --shadow-2: 0 2px 6px 2px rgba(60, 64, 67, 0.15), 0 1px 2px 0 rgba(60, 64, 67, 0.3);
  --shadow-3: 0 8px 10px 1px rgba(60, 64, 67, 0.14), 0 3px 14px 2px rgba(60, 64, 67, 0.12), 0 5px 5px -3px rgba(60, 64, 67, 0.2);
  --row-shadow: inset 1px 0 0 #dadce0, inset -1px 0 0 #dadce0, 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);

  --row-h: 40px;
  --header-h: 64px;
  --sidebar-w: 256px;
  --rail-w: 72px;
  color-scheme: light;
}

:root[data-theme='dark'] {
  --accent: #a8c7fa;
  --accent-hover: #c2d7fb;
  --accent-container: #0842a0;
  --on-accent-container: #d3e3fd;
  --accent-tint: #2b4470;
  --compose: #0b3a6f;
  --compose-hover: #0f4a8c;
  --on-compose: #d3e3fd;
  --on-accent: #062e6f;

  --bg: #111318;
  --surface: #1b1d22;
  --surface-read: #16181c;
  --surface-search: #262a31;
  --surface-search-focus: #2b3038;
  --surface-raised: #2a2d34;
  --text: #e3e3e3;
  --text-2: #c4c7c5;
  --text-3: #a9adb1;
  --text-4: #8a8f94;
  --line: #33363c;
  --line-strong: #4a4d54;
  --hover: rgba(255, 255, 255, 0.09);
  --hover-strong: rgba(255, 255, 255, 0.14);
  --star: #f5b400;
  --danger: #f2b8b5;
  --danger-container: #601410;
  --success: #6dd58c;
  --scrim: rgba(0, 0, 0, 0.55);
  --tooltip-bg: #e3e3e3;
  --shadow-1: 0 1px 2px 0 rgba(0, 0, 0, 0.6), 0 1px 3px 1px rgba(0, 0, 0, 0.4);
  --shadow-2: 0 2px 6px 2px rgba(0, 0, 0, 0.45), 0 1px 2px 0 rgba(0, 0, 0, 0.6);
  --shadow-3: 0 8px 10px 1px rgba(0, 0, 0, 0.5), 0 3px 14px 2px rgba(0, 0, 0, 0.4);
  --row-shadow: inset 1px 0 0 #4a4d54, inset -1px 0 0 #4a4d54, 0 1px 2px 0 rgba(0, 0, 0, 0.6), 0 1px 3px 1px rgba(0, 0, 0, 0.4);
  color-scheme: dark;
}

:root[data-accent='coral'] {
  --accent: #b5401a;
  --accent-hover: #9c3514;
  --accent-container: #ffdbcf;
  --on-accent-container: #3b0d00;
  --accent-tint: #ffd0bf;
  --compose: #ffcfbd;
  --compose-hover: #ffc0aa;
  --on-compose: #3b0d00;
}
:root[data-accent='green'] {
  --accent: #146c2e;
  --accent-hover: #0f5a25;
  --accent-container: #c4eed0;
  --on-accent-container: #002106;
  --accent-tint: #b3e6c2;
  --compose: #b8ebc8;
  --compose-hover: #a6e0b8;
  --on-compose: #002106;
}
:root[data-accent='violet'] {
  --accent: #6750a4;
  --accent-hover: #563f93;
  --accent-container: #e8ddff;
  --on-accent-container: #21005d;
  --accent-tint: #dccfff;
  --compose: #e6d9ff;
  --compose-hover: #d9c8ff;
  --on-compose: #21005d;
}
:root[data-theme='dark'][data-accent='coral'] {
  --accent: #ffb59d;
  --accent-hover: #ffc8b6;
  --accent-container: #7a2b0d;
  --on-accent-container: #ffdbcf;
  --accent-tint: #5c3222;
  --compose: #6d2a10;
  --compose-hover: #813416;
  --on-compose: #ffdbcf;
  --on-accent: #5b1a00;
}
:root[data-theme='dark'][data-accent='green'] {
  --accent: #82d99a;
  --accent-hover: #9ee6b1;
  --accent-container: #0a5326;
  --on-accent-container: #c4eed0;
  --accent-tint: #24462f;
  --compose: #0c4a22;
  --compose-hover: #135e2e;
  --on-compose: #c4eed0;
  --on-accent: #00391a;
}
:root[data-theme='dark'][data-accent='violet'] {
  --accent: #cfbcff;
  --accent-hover: #ddd0ff;
  --accent-container: #4f378b;
  --on-accent-container: #eaddff;
  --accent-tint: #3d3358;
  --compose: #45307f;
  --compose-hover: #553d9a;
  --on-compose: #eaddff;
  --on-accent: #381e72;
}

:root[data-density='comfortable'] {
  --row-h: 48px;
}
:root[data-density='compact'] {
  --row-h: 32px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family: var(--font-ui);
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
input,
textarea,
select {
  font: inherit;
  color: inherit;
}
a {
  color: var(--accent);
}
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
button:focus-visible {
  outline-offset: 0;
}
::selection {
  background: color-mix(in srgb, var(--accent) 28%, transparent);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* scrollbars */
* {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text-3) 40%, transparent) transparent;
}
::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
::-webkit-scrollbar-thumb {
